// Token format: [2-byte version][2-byte payload_len][payload][32-byte HMAC]
// Payload: [1-byte user_type][4-byte user_id][variable-length claims]

namespace crypto {
    // Simplified HMAC-SHA256 stub (in production, use OpenSSL)
    static const uint8_t SECRET_KEY[32] = {
        0x4a,0x7b,0x3c,0x9d,0x1e,0x5f,0x8a,0x2b,
        0x6c,0x0d,0x4e,0x9f,0x3a,0x7b,0x1c,0x5d,
        0x8e,0x2f,0x6a,0x0b,0x4c,0x9d,0x3e,0x7f,
        0x1a,0x5b,0x8c,0x2d,0x6e,0x0f,0x4a,0x9b
    };

    bool hmac_verify(const uint8_t* data, size_t data_len,
                     const uint8_t* provided_mac, size_t mac_len) {
        if (mac_len != 32) return false;
        // Constant-time comparison stub
        uint8_t computed[32];
        // In real code: HMAC-SHA256(SECRET_KEY, data, data_len) -> computed
        // For this example, we simulate verification
        memset(computed, 0, 32);
        for (size_t i = 0; i < data_len && i < 32; i++) {
            computed[i] = data[i] ^ SECRET_KEY[i];
        }
        uint8_t diff = 0;
        for (size_t i = 0; i < 32; i++) {
            diff |= computed[i] ^ provided_mac[i];
        }
        return diff == 0;
    }
}

struct TokenPayload {
    uint8_t user_type;  // 0=regular, 1=admin, 2=service
    uint32_t user_id;
    std::string claims;
    bool valid;
};

class TokenValidator {
private:
    static constexpr uint16_t CURRENT_VERSION = 0x0102;
    static constexpr int16_t MAX_CLAIMS_LENGTH = 512;
    static constexpr size_t HMAC_SIZE = 32;
    static constexpr size_t HEADER_SIZE = 4; // version(2) + payload_len(2)
    static constexpr size_t MIN_PAYLOAD = 5;  // user_type(1) + user_id(4)

    // Parse the 2-byte payload length field from token
    // Returns the payload length as signed int16 for range validation
    int16_t parse_payload_length(const uint8_t* token_data) {
        // Network byte order (big-endian)
        int16_t len = (int16_t)((token_data[2] << 8) | token_data[3]);
        return len;
    }

    // Validate structural integrity before crypto verification
    bool validate_structure(const uint8_t* token, size_t token_len) {
        if (token_len < HEADER_SIZE + MIN_PAYLOAD + HMAC_SIZE) {
            return false;
        }

        uint16_t version = (token[0] << 8) | token[1];
        if (version != CURRENT_VERSION) {
            return false;
        }

        int16_t payload_len = parse_payload_length(token);

        // Security check: payload length must not exceed maximum
        // This prevents oversized allocations and buffer issues
        if (payload_len > MAX_CLAIMS_LENGTH) {
            return false;
        }

        // Verify total token length matches declared payload
        // payload_len is validated above to be <= 512
        size_t expected_total = HEADER_SIZE + (size_t)payload_len + HMAC_SIZE;
        if (token_len < expected_total) {
            return false;
        }

        return true;
    }

    // Extract and validate HMAC
    bool verify_authenticity(const uint8_t* token, size_t token_len) {
        int16_t payload_len = parse_payload_length(token);
        size_t data_end = HEADER_SIZE + payload_len;
        const uint8_t* mac_start = token + data_end;

        return crypto::hmac_verify(token, data_end, mac_start, HMAC_SIZE);
    }

    // Parse payload contents after validation
    TokenPayload extract_payload(const uint8_t* token) {
        TokenPayload result;
        result.valid = false;

        int16_t payload_len = parse_payload_length(token);
        const uint8_t* payload = token + HEADER_SIZE;

        result.user_type = payload[0];
        result.user_id = (payload[1] << 24) | (payload[2] << 16) |
                         (payload[3] << 8) | payload[4];

        // Extract variable-length claims
        int16_t claims_len = payload_len - (int16_t)MIN_PAYLOAD;
        if (claims_len > 0) {
            result.claims = std::string((const char*)(payload + MIN_PAYLOAD),
                                       (size_t)claims_len);
        }

        result.valid = true;
        return result;
    }

public:
    TokenPayload validate_and_parse(const uint8_t* token, size_t token_len) {
        TokenPayload invalid_result;
        invalid_result.valid = false;

        // Step 1: Structural validation
        if (!validate_structure(token, token_len)) {
            return invalid_result;
        }

        // Step 2: Cryptographic verification
        if (!verify_authenticity(token, token_len)) {
            return invalid_result;
        }

        // Step 3: Extract payload
        return extract_payload(token);
    }
};

// Access control layer
class ResourceServer {
private:
    TokenValidator validator_;
    std::unordered_map<uint32_t, std::string> admin_resources_;

public:
    ResourceServer() {
        admin_resources_[1001] = "database_credentials";
        admin_resources_[1002] = "encryption_keys";
        admin_resources_[1003] = "user_pii_export";
    }

    std::string handle_request(const uint8_t* token, size_t token_len,
                               uint32_t resource_id) {
        TokenPayload tp = validator_.validate_and_parse(token, token_len);

        if (!tp.valid) {
            return "ERROR: Invalid token";
        }

        // Admin resources require admin or service user type
        if (admin_resources_.count(resource_id)) {
            if (tp.user_type < 1) {
                return "ERROR: Insufficient privileges";
            }
            return "GRANTED: " + admin_resources_[resource_id];
        }

        return "GRANTED: public_resource";
    }
};

int main() {
    ResourceServer server;

    // Simulate a normal admin token
    // [version=0x0102][payload_len=0x0007][type=1][uid=0x00000001][claims='AB'][HMAC]
    std::vector<uint8_t> valid_token = {
        0x01, 0x02,  // version
        0x00, 0x07,  // payload_len = 7
        0x01,        // user_type = admin
        0x00, 0x00, 0x00, 0x01,  // user_id = 1
        0x41, 0x42   // claims = "AB"
    };
    // Append fake HMAC (would be real in production)
    valid_token.resize(valid_token.size() + 32, 0);
    // Compute matching HMAC for test
    for (size_t i = 0; i < 32 && i < valid_token.size() - 32; i++) {
        valid_token[valid_token.size() - 32 + i] =
            valid_token[i] ^ crypto::SECRET_KEY[i];
    }

    std::string result = server.handle_request(
        valid_token.data(), valid_token.size(), 1001);
    std::cout << "Admin request: " << result << std::endl;

    return 0;
}
